        function getTaskSetForDay(day) {
            const rank = rankForDayL(day);
            const set = TASKS_BY_RANK[rank.day] || TASKS_BY_RANK[0];
            const index = Math.max(0, day - rank.day) % 30;
            const pick = item => isEn() ? item.en : item.ru;
            return { rankDay: rank.day, rankName: rank.name, index, spirit: pick(set.spirit[index]), mind: pick(set.mind[index]), body: pick(set.body[index]) };
        }

